// 72-hour exponential decay window. Acute mitochondrial response peaks 3-6h
// post-treatment and largely fades by 24-48h, gone by ~72h. Half-life ~18h
// so a session is at full intensity at t=0, ~50% at 18h, ~25% at 36h, ~6% at 72h.
const FADE_HOURS = 72;
const HALF_LIFE_HOURS = 18;
// decayFactor(timestamp) returns a value in [0, 1]. Returns 0 once we're past FADE_HOURS.
function decayFactor(ts) {
  const hours = (Date.now() - ts) / 3600000;
  if (hours >= FADE_HOURS) return 0;
  return Math.exp(-hours * Math.LN2 / HALF_LIFE_HOURS);
}
// Anatomical hand bounding boxes on the BODY display, measured from the source image.
// FRONT view: viewer faces person, mirrored — your LEFT hand on viewer's RIGHT.
// BACK view: viewer faces person's back — your LEFT hand on viewer's LEFT (same side).
const HAND_BODY_BBOX = {
  "hand-left-palm":  { bodyView: "front", x1: 153, y1: 249, x2: 186, y2: 286 },
  "hand-right-palm": { bodyView: "front", x1: 24,  y1: 249, x2: 51,  y2: 286 },
  "hand-left-back":  { bodyView: "back",  x1: 157, y1: 249, x2: 186, y2: 286 },
  "hand-right-back": { bodyView: "back",  x1: 23,  y1: 249, x2: 51,  y2: 286 },
};

// The hand image inside the hand panel: fills ~86% of width (centered), ~92% of height
// (top to bottom), with fingers at TOP and wrist at BOTTOM.
const HAND_IMG_BBOX_IN_PANEL = {
  // Fraction of HAND_W (210) and HAND_H (380) that the actual hand drawing occupies.
  xMin: 0.07, xMax: 0.93,   // ~14px to ~196px out of 210
  yMin: 0.04, yMax: 0.96,   // ~15px to ~365px out of 380
};

// Project a click position on a hand panel to the corresponding (x, y) on the body view.
// Returns { bodyView, x, y } or null if the projection fails.
function projectHandClickToBody(handView, panelX, panelY, isMirrored) {
  const bbox = HAND_BODY_BBOX[handView];
  if (!bbox) return null;
  const ib = HAND_IMG_BBOX_IN_PANEL;

  // Convert panel coords (0..HAND_W, 0..HAND_H) to fractional position within the hand image.
  // If the hand panel is mirrored (e.g. left hand mirrored from right-hand reference image),
  // then a click at panel x=p maps to image x=HAND_W-p.
  const imgPanelX = isMirrored ? (HAND_W - panelX) : panelX;
  const fracX = (imgPanelX / HAND_W - ib.xMin) / (ib.xMax - ib.xMin);
  const fracY = (panelY / HAND_H - ib.yMin) / (ib.yMax - ib.yMin);

  // The reference image is a RIGHT hand, palm up, fingers at TOP, thumb on viewer's right.
  // The body view shows hands HANGING DOWN with palms facing inward (front view).
  // So the body's "fingers down, wrist up" means we FLIP Y.
  // X mapping for front view (palm of left hand on viewer's right side of front):
  //   panel x increases left→right; on body, x within bbox also increases left→right.
  //   Both panels show palm side, so x mapping is direct.
  const bodyX = bbox.x1 + fracX * (bbox.x2 - bbox.x1);
  const bodyY = bbox.y2 - fracY * (bbox.y2 - bbox.y1);  // Y is flipped

  return { bodyView: bbox.bodyView, x: bodyX, y: bodyY };
}

const STORAGE_KEY = "celluma-v18";
const DISPLAY_H = 500;
const DISPLAY_W = 210;

// Heat scale: 3 discrete crisp bands (peach → coral → raspberry) with hard transitions.
// No smooth gradient — each dose level is one of three clean colors.
const HEAT_BANDS = [
  { threshold: 0,  rgb: [255, 183, 167] }, // peach pink (low / fresh)
  { threshold: 8,  rgb: [255, 122, 122] }, // coral (medium / solid coverage)
  { threshold: 18, rgb: [217, 70, 110] },  // raspberry (heavy / warning)
];

// Kept for backwards compat where some code references HEAT_STOPS[i]; we map to the band colors.
const HEAT_STOPS = [
  { t: 0.0,  rgb: HEAT_BANDS[0].rgb },
  { t: 0.33, rgb: HEAT_BANDS[1].rgb },
  { t: 0.67, rgb: HEAT_BANDS[2].rgb },
  { t: 1.0,  rgb: HEAT_BANDS[2].rgb },
];

const SATURATION_JOULES = 30;

function interpColor(t) {
  // t is in [0,1]; convert back to joules via SATURATION_JOULES and pick the right band
  const joules = t * SATURATION_JOULES;
  let chosen = HEAT_BANDS[0];
  for (const band of HEAT_BANDS) {
    if (joules >= band.threshold) chosen = band;
  }
  return chosen.rgb;
}

function exposureToColor(joules) {
  if (joules <= 0) return null;
  const t = Math.min(1, joules / SATURATION_JOULES);
  const [r, g, b] = interpColor(t);
  // Discrete bands deserve consistent opacity (no in-between ramping).
  // Peach (low) still semi-transparent; coral and raspberry render more solid.
  let alpha = 0.55;
  if (joules >= 8)  alpha = 0.75;
  if (joules >= 18) alpha = 0.88;
  return `rgba(${r},${g},${b},${alpha.toFixed(2)})`;
}

